// Deduplication: Skip messages seen within the last 2 minutes
const DEDUP_WINDOW_MS = 2 * 60 * 1000; // 2 minutes

const staticData = $getWorkflowStaticData('global');
if (!staticData.messageHashes) {
  staticData.messageHashes = {};
}

const now = Date.now();

// Clean up expired entries
for (const hash in staticData.messageHashes) {
  if (now - staticData.messageHashes[hash] > DEDUP_WINDOW_MS) {
    delete staticData.messageHashes[hash];
  }
}

// Get the raw input payload
const rawPayload = $input.first().json;

// Create hash from the entire payload using cyrb53 (64-bit, low collision)
const payloadStr = JSON.stringify(rawPayload);
const cyrb53 = (str, seed = 0) => {
  let h1 = 0xdeadbeef ^ seed, h2 = 0x41c6ce57 ^ seed;
  for (let i = 0, ch; i < str.length; i++) {
    ch = str.charCodeAt(i);
    h1 = Math.imul(h1 ^ ch, 2654435761);
    h2 = Math.imul(h2 ^ ch, 1597334677);
  }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507);
  h1 ^= Math.imul(h2 ^ (h2 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507);
  h2 ^= Math.imul(h1 ^ (h1 >>> 13), 3266489909);
  return (4294967296 * (2097151 & h2) + (h1 >>> 0)).toString(36);
};
const hash = cyrb53(payloadStr);

// Check for duplicate
if (staticData.messageHashes[hash]) {
  return [{ json: { isDuplicate: true, hash } }];
}

// Store hash and pass through
staticData.messageHashes[hash] = now;

return [{
  json: {
    isDuplicate: false,
    hash,
    rawPayload,
    receivedAt: new Date().toISOString()
  }
}];

// Prepare message for AI Agent
const input = $input.first().json;
const rawPayload = input.rawPayload;
const receivedAt = input.receivedAt;

// Format the payload as a string for the AI
const payloadStr = JSON.stringify(rawPayload, null, 2);

const chatInput = `Webhook payload received at ${receivedAt}:\n\n${payloadStr}\n\nAnalyze this payload, determine what type of message it is (alert or notification), extract relevant information, and enrich it appropriately. Use available tools if needed to gather additional context.`;

return [{
  json: {
    rawPayload,
    receivedAt,
    chatInput
  }
}];

