      "type": "array",
      "items": { "type": "string" },
      "description": "Only specific actions based on findings. Empty if nothing actionable."
    },
    "source": {
      "type": "string"
    }
  },
  "required": ["message_type", "title", "severity", "emoji", "summary", "source"]
}

