// Format enriched message as HTML for Telegram
const output = $input.first().json.output;

const escapeHtml = (text) => {
  if (!text) return '';
  return String(text)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
};

const emoji = output.emoji || '🔔';
const title = escapeHtml(output.title || 'Message');
const summary = escapeHtml(output.summary || '');

const message = `${emoji} <b>${title}</b>\n\n${summary}`;

// Alerts play sound, notifications are silent
const disableNotification = output.message_type === 'notification';

return [{ json: { message, messageType: output.message_type, disableNotification, success: true } }];

// Fallback formatter when AI enrichment fails
// Get input from the item that triggered this branch (via AI Agent error output)
const currentItem = $input.first().json;

// Try to get context from Prepare AI Context node, fall back to current item
let rawPayload, receivedAt;
try {
  const preparedContext = $('Prepare AI Context').first().json;
  rawPayload = preparedContext.rawPayload;
  receivedAt = preparedContext.receivedAt;
} catch (e) {
  // If Prepare AI Context isn't accessible, try to extract from current item
  rawPayload = currentItem.rawPayload || currentItem;
  receivedAt = currentItem.receivedAt || new Date().toISOString();
}

const escapeHtml = (text) => {
  if (!text) return '';
  return String(text)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
};

// Try to extract some basic info from common payload formats
let title = 'Webhook Message';
let source = 'unknown';

if (rawPayload.eventType) {
  // *arr format
  title = rawPayload.eventType;
  source = rawPayload.instanceName || 'arr';
} else if (rawPayload.alertname) {
  // AlertManager format
  title = rawPayload.alertname;
  source = 'alertmanager';
} else if (rawPayload.event_type) {
  // Home Assistant format
  title = rawPayload.event_type;
  source = 'homeassistant';
}

const payloadStr = escapeHtml(JSON.stringify(rawPayload, null, 2));

const telegramMessage = `🔔 <b>${escapeHtml(title)}</b>\n\n⚠️ <i>AI enrichment unavailable</i>\n\n<b>Source:</b> ${escapeHtml(source)}\n<b>Received:</b> ${escapeHtml(receivedAt)}\n\n<b>Raw Payload:</b>\n<pre>${payloadStr}</pre>`;

// Fallback always plays sound (assume it's important)
return [{ json: { message: telegramMessage, disableNotification: false, success: false } }];
